#include<bits/stdc++.h>
using namespace std;
#define ll long long
ll lsc[62],rsc[62],rsc2[62];
char s[62];
map<pair<ll,int>,ll>nm,mm;
ll comb(int n,int k)
{
    if (n<k || k<0)
        return 0;
    ll rez=1,i;
    for(i=0;i<k;i++)
        rez=rez*(n-i)/(i+1);
    return rez;
}
int main()
{
    //freopen(".in","r",stdin);
    //freopen(".out","w",stdout);
    int r,c,n,i,cnta=0,cntb=0,ok,ast,bst;
    ll msum=0,nsum=0,bsum,rasp=0;
    scanf("%d%d\n",&r,&c);
    n=2*(r+c);
    scanf("%s",&s);
    lsc[2*r-1]=1;
    for(i=2*r;i<n;i++)
        lsc[i]=lsc[i-1]*i/(1ll*i-1ll*2*r+1ll);
    for(i=0;i<=n;i++)
        {
        rsc[i]=comb(i,r);
        rsc2[i]=comb(i,r-1);
        }
    nsum=rsc[n/2]*rsc[n/2];
    for(i=n-1;i>=0;i--)
        {
        if (msum>0)
            ok=1;
        else
            ok=0;
        if (cntb==n/2)
            ok=1;
        if (cnta==n/2)
            ok=0;
        if (ok)
            {
            cnta++;
            msum=msum-rsc2[n/2-cnta]*rsc[n/2-cntb];
            }
        else
            {
            cntb++;
            msum=msum+rsc2[n/2-cntb]*rsc[n/2-cnta];
            }
        }
    msum=max(msum,-msum);
    mm[make_pair(0,0)]=1;
    for(i=n-1;i>=2*r-1;i--)
        {
        nm.clear();
        for(auto it:mm)
            {
            ll sum=it.first.first,ncnt=it.second,asum,bsum;
            int cnt=it.first.second;
            ast=n/2-cnt;
            bst=i+1-ast;
            asum=sum+rsc2[ast-1]*rsc[bst];
            bsum=sum-rsc2[bst-1]*rsc[ast];
            if (s[i]=='A')
                {
                nm[make_pair(asum,cnt+1)]+=ncnt;
                nm[make_pair(bsum,cnt)]+=0;
                }
            else
                if (s[i]=='B')
                    {
                    nm[make_pair(asum,cnt+1)]+=0;
                    nm[make_pair(bsum,cnt)]+=ncnt;
                    }
                else
                    {
                    nm[make_pair(asum,cnt+1)]+=ncnt;
                    nm[make_pair(bsum,cnt)]+=ncnt;
                    }
            }
        nsum=nsum-lsc[i];
        mm.clear();
        for(auto it:nm)
            {
            ll sum=it.first.first,ncnt=it.second;
            int cnt=it.first.second;
            ast=n/2-cnt;
            bst=i-ast;
            if (cnt>n/2 || n-i-cnt>n/2)
                continue;
            if (sum<-msum-rsc[ast]*rsc[bst] || sum>msum+rsc[ast]*rsc[bst])
                continue;
            mm[make_pair(sum,cnt)]+=ncnt;
            }
        }
    bsum=1e18;
    for(auto it:mm)
        bsum=min(bsum,max(it.first.first,-it.first.first));
    for(auto it:mm)
        {
        ll sum=it.first.first,ncnt=it.second;
        int cnt=it.first.second;
        if (sum==bsum || sum==-bsum)
            {
            int sem=0;
            for(i=0;i<2*r-1;i++)
                if (s[i]=='?')
                    sem++;
                else
                    if (s[i]=='A')
                        cnt++;
            ncnt=ncnt*comb(sem,n/2-cnt);
            rasp+=ncnt;
            }
        }
    printf("%lld\n",rasp);
return 0;
}

